import test from 'node:test';
import assert from 'node:assert/strict';
import { createInvoice, issueInvoice, invoiceTotals, lineTotal, lineDiscount, lineVAT } from '../src/invoices.js';
import { recordPayment, balanceDue } from '../src/payments.js';
import { overdueInvoices, vatSummary } from '../src/reports.js';

test('overdueInvoices returns empty array for no invoices', () => {
  const result = overdueInvoices([], '2026-10-07');
  assert.equal(result.ok, true);
  assert.equal(result.value.length, 0);
});

test('overdueInvoices rejects invalid asOf date', () => {
  const result = overdueInvoices([], '2026-13-01');
  assert.equal(result.ok, false);
  assert.equal(result.error, 'DATE_INVALID');
});

test('overdueInvoices excludes draft invoices', () => {
  const inv = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
    terms: 'NET14',
  });
  const result = overdueInvoices([inv.value], '2026-10-20');

  assert.equal(result.ok, true);
  assert.equal(result.value.length, 0);
});

test('overdueInvoices excludes paid invoices', () => {
  const inv = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
    terms: 'NET14',
  });
  const issued = issueInvoice(inv.value, []);
  const totals = invoiceTotals(issued.value);
  const paid = recordPayment(issued.value, { amount: totals.total, date: '2026-10-08' });

  const result = overdueInvoices([paid.value], '2026-10-20');

  assert.equal(result.ok, true);
  assert.equal(result.value.length, 0);
});

test('overdueInvoices includes issued invoices with overdue dueDate', () => {
  const inv = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
    terms: 'NET14',
  });
  const issued = issueInvoice(inv.value, []);

  const result = overdueInvoices([issued.value], '2026-10-20');

  assert.equal(result.ok, true);
  assert.equal(result.value.length, 1);
  assert.equal(result.value[0].number, issued.value.number);
});

test('overdueInvoices includes partially_paid invoices with overdue dueDate', () => {
  const inv = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
    terms: 'NET14',
  });
  const issued = issueInvoice(inv.value, []);
  const totals = invoiceTotals(issued.value);
  const partial = recordPayment(issued.value, { amount: Math.floor(totals.total / 2), date: '2026-10-08' });

  const result = overdueInvoices([partial.value], '2026-10-20');

  assert.equal(result.ok, true);
  assert.equal(result.value.length, 1);
});

test('overdueInvoices excludes invoices with dueDate equal to asOf', () => {
  const inv = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
    terms: 'NET14',
  });
  const issued = issueInvoice(inv.value, []);

  const result = overdueInvoices([issued.value], '2026-10-15');

  assert.equal(result.ok, true);
  assert.equal(result.value.length, 0);
});

test('overdueInvoices excludes invoices with dueDate after asOf', () => {
  const inv = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
    terms: 'NET14',
  });
  const issued = issueInvoice(inv.value, []);

  const result = overdueInvoices([issued.value], '2026-10-14');

  assert.equal(result.ok, true);
  assert.equal(result.value.length, 0);
});

test('overdueInvoices calculates daysOverdue correctly', () => {
  const inv = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
    terms: 'NET14',
  });
  const issued = issueInvoice(inv.value, []);

  const result = overdueInvoices([issued.value], '2026-10-20');

  assert.equal(result.value[0].daysOverdue, 5);
});

test('overdueInvoices includes due amount from balanceDue', () => {
  const inv = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
    terms: 'NET14',
  });
  const issued = issueInvoice(inv.value, []);
  const due = balanceDue(issued.value);

  const result = overdueInvoices([issued.value], '2026-10-20');

  assert.equal(result.value[0].due, due);
});

test('overdueInvoices includes customerId in report', () => {
  const inv = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
    terms: 'NET14',
  });
  const issued = issueInvoice(inv.value, []);

  const result = overdueInvoices([issued.value], '2026-10-20');

  assert.equal(result.value[0].customerId, 'C-002');
});

test('overdueInvoices includes dueDate in report', () => {
  const inv = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
    terms: 'NET14',
  });
  const issued = issueInvoice(inv.value, []);

  const result = overdueInvoices([issued.value], '2026-10-20');

  assert.equal(result.value[0].dueDate, '2026-10-15');
});

test('overdueInvoices sorts by most overdue first', () => {
  const inv1 = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
    terms: 'NET14',
  });
  const inv2 = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-05',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
    terms: 'NET14',
  });

  const issued1 = issueInvoice(inv1.value, []);
  const issued2 = issueInvoice(inv2.value, ['INV-001']);

  const result = overdueInvoices([issued2.value, issued1.value], '2026-10-25');

  assert.equal(result.value[0].dueDate, '2026-10-15');
  assert.equal(result.value[1].dueDate, '2026-10-19');
});

test('overdueInvoices with payment reduces due amount', () => {
  const inv = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
    terms: 'NET14',
  });
  const issued = issueInvoice(inv.value, []);
  const totals = invoiceTotals(issued.value);
  const half = Math.floor(totals.total / 2);
  const partial = recordPayment(issued.value, { amount: half, date: '2026-10-08' });

  const result = overdueInvoices([partial.value], '2026-10-20');

  assert.equal(result.value[0].due, half);
});

test('overdueInvoices with different terms', () => {
  const inv14 = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
    terms: 'NET14',
  });
  const inv30 = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
    terms: 'NET30',
  });

  const issued14 = issueInvoice(inv14.value, []);
  const issued30 = issueInvoice(inv30.value, ['INV-001']);

  const result = overdueInvoices([issued14.value, issued30.value], '2026-10-20');

  assert.equal(result.value.length, 1);
  assert.equal(result.value[0].number, issued14.value.number);
});

test('overdueInvoices with EOM terms', () => {
  const inv = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
    terms: 'EOM',
  });

  const issued = issueInvoice(inv.value, []);

  const result = overdueInvoices([issued.value], '2026-11-01');

  assert.equal(result.ok, true);
  assert.equal(result.value.length, 1);
  assert.equal(result.value[0].daysOverdue, 1);
});

test('overdueInvoices with multiple customers', () => {
  const inv1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
    terms: 'NET14',
  });
  const inv2 = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
    terms: 'NET14',
  });

  const issued1 = issueInvoice(inv1.value, []);
  const issued2 = issueInvoice(inv2.value, ['INV-001']);

  const result = overdueInvoices([issued1.value, issued2.value], '2026-10-20');

  assert.equal(result.value.length, 2);
  assert.equal(result.value[0].customerId, 'C-001');
  assert.equal(result.value[1].customerId, 'C-002');
});

test('overdueInvoices report structure', () => {
  const inv = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
    terms: 'NET14',
  });
  const issued = issueInvoice(inv.value, []);

  const result = overdueInvoices([issued.value], '2026-10-20');

  const item = result.value[0];
  assert('number' in item);
  assert('customerId' in item);
  assert('dueDate' in item);
  assert('daysOverdue' in item);
  assert('due' in item);
  assert.equal(Object.keys(item).length, 5);
});

test('overdueInvoices with mix of overdue and current invoices', () => {
  const inv1 = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
    terms: 'NET14',
  });
  const inv2 = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-05',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
    terms: 'NET30',
  });

  const issued1 = issueInvoice(inv1.value, []);
  const issued2 = issueInvoice(inv2.value, ['INV-001']);

  const result = overdueInvoices([issued1.value, issued2.value], '2026-10-20');

  assert.equal(result.value.length, 1);
  assert.equal(result.value[0].number, issued1.value.number);
