  for (let i = 0; i < 20; i++) {
    const inv = createInvoice({
      customerId: 'C-002',
      issueDate: '2026-10-07',
      lines: [{ sku: 'DES-HOUR', qty: i + 1 }],
    });
    const issued = issueInvoice(inv.value, invoices.length > 0 ? [`INV-${invoices.length}`] : []);
    invoices.push(issued.value);
  }

  const result = vatSummary(invoices);

  assert.equal(result.ok, true);
  assert(result.value.length > 0);
});

test('vatSummary with various discount percentages', () => {
  const inv = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 1, discountPercent: 0 },
      { sku: 'DES-HOUR', qty: 1, discountPercent: 5 },
      { sku: 'DES-HOUR', qty: 1, discountPercent: 10 },
      { sku: 'DES-HOUR', qty: 1, discountPercent: 20 },
    ],
  });
  const issued = issueInvoice(inv.value, []);

  const result = vatSummary([issued.value]);

  assert.equal(result.ok, true);
  let totalBase = 0;
  let totalVat = 0;
  for (const line of issued.value.lines) {
    totalBase += lineTotal(line) - lineDiscount(line);
    totalVat += lineVAT(line);
  }
  assert.equal(result.value[0].base, totalBase);
  assert.equal(result.value[0].vat, totalVat);
});

